export const outlineChapters=['第一章　绪论','　1.1 研究背景与意义','　1.2 研究问题与研究目标','第二章　文献综述与理论基础','　2.1 相关研究进展','　2.2 理论基础','第三章　研究设计','　3.1 研究方法与研究对象','　3.2 数据来源与分析思路','第四章　结果与讨论（依据实际研究填写）','第五章　结论与展望','参考文献（填写真实来源）'];
export function buildOutline(v){return [v.title,`${v.mode} · ${v.degree} · ${v.major||'学科待填写'}`,'',...outlineChapters,'',v.targetWords?'目标字数：'+v.targetWords+' 字':'',v.method?'研究方法：'+v.method:'',v.requirements?'研究要求：'+v.requirements:'','本地结构模板：请依据真实研究完善；未调用 AI 或分析参考材料。'].filter(Boolean).join('\n');}
export function reconcileSections(outline,previous=[]){const titles=[...new Set(outline.split('\n').map(l=>l.trim()).filter(l=>/^第[^\s]{1,12}章/.test(l)||/^参考文献/.test(l)))];if(!titles.length)titles.push('正文');const next=titles.map(title=>{const old=previous.find(s=>s.title===title);return {id:old?.id||crypto.randomUUID(),title,text:old?.text||'',retained:false};});return [...next,...previous.filter(s=>!titles.includes(s.title)&&s.text.trim()).map(s=>({...s,retained:true}))];}
export function composeBody(v,sections){return [v.title,`${v.mode} · ${v.degree} · ${v.major||'学科待填写'}`,...sections.filter(s=>s.text.trim()).flatMap(s=>['',s.title,s.text])].join('\n');}
